def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # {key: (value, write_time)}
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries
            keys_to_delete = []
            for k, (v, write_time) in cache.items():
                if write_time + ttl <= t:
                    keys_to_delete.append(k)
            for k in keys_to_delete:
                del cache[k]

            # If key exists, remove it (will re-add at end to mark as most recently used)
            if key in cache:
                del cache[key]
            # If cache is at capacity and key is new, evict LRU
            elif len(cache) >= capacity:
                cache.popitem(last=False)

            # Add/update the entry
            cache[key] = (value, t)

        elif op[0] == 'get':
            _, t, key = op

            # Remove expired entries
            keys_to_delete = []
            for k, (v, write_time) in cache.items():
                if write_time + ttl <= t:
                    keys_to_delete.append(k)
            for k in keys_to_delete:
                del cache[k]

            # Try to get the key
            if key in cache:
                value, write_time = cache[key]
                # Mark as most recently used by moving to end
                del cache[key]
                cache[key] = (value, write_time)
                results.append(value)
            else:
                results.append(-1)

    return results

